eyes=[
 dict(id="michitsuna-mother",name="Michitsuna's Mother (Fujiwara no Michitsuna no Haha)",life="c. 935–995",role="Secondary wife of the rising minister Fujiwara no Kaneie; poet; mother of Michitsuna",side="Fujiwara court aristocracy (northern house, by marriage)",where="Her own house in the capital, waiting on Kaneie's visits",vantage=2,vantage_label="prologue: a wife at the edge of the regent's household",form="memoir-diary (nikki, written retrospectively in part)",language="Classical Japanese (kana)",authenticity="Kagerō Nikki survives only in late copies; the first book is plainly retrospective, while the later years read closer to a running diary. The author's personal name is unknown.",bio="Her Kagerō Nikki (954–974) is the earliest surviving kana diary by a woman, an often bitter record of marriage to Kaneie, Michinaga's father. She is the generation before the rival salons, and her niece wrote the Sarashina Nikki, which makes her the chapter's prologue and its family hinge.",sources=[{"title":"Sarashina Nikki (Wikipedia) - notes the author's aunt wrote the Kagerō Nikki","url":"https://en.wikipedia.org/wiki/Sarashina_Nikki"}]),
 dict(id="sei",name="Sei Shōnagon",life="c. 966–after 1017",role="Lady-in-waiting to Empress Teishi, c. 993–1000; poet's daughter (Kiyohara no Motosuke)",side="Teishi's salon (the Michitaka branch of the Fujiwara, Michinaga's rivals)",where="Teishi's quarters in the palace and her temporary residences",vantage=1,vantage_label="inside the losing salon",form="zuihitsu (miscellany: lists, sketches and some datable diary-like episodes)",language="Classical Japanese (kana)",authenticity="Makura no Sōshi is not a diary. It survives in several textual lines that order and contain different material. Only some episodes can be dated, and these are dated by scholars from internal evidence, so most dates here are approximate.",bio="Witty, competitive and openly proud of her Chinese learning, she wrote about Teishi's court as a place of brilliance and almost never mentions its ruin: the exile of Teishi's brothers in 996 and Michinaga's takeover. Her silences say as much as her lists do.",sources=[{"title":"Gendai Business: dated Pillow Book passages (flute, 1000) set against the diaries","url":"https://gendai.media/articles/-/127981"},{"title":"President Online: the last datable Pillow Book passage and Teishi's death in Gonki","url":"https://president.jp/articles/-/83790"}]),
 dict(id="murasaki",name="Murasaki Shikibu",life="c. 973–c. 1014 or later (perhaps c. 1025)",role="Widowed author of the Tale of Genji; lady-in-waiting to Empress Shōshi from 1005 or 1006",side="Shōshi's salon (Michinaga's household)",where="Michinaga's Tsuchimikado mansion and the palace",vantage=1,vantage_label="eyewitness inside the winning salon",form="diary (nikki) with an embedded undated letter section",language="Classical Japanese (kana)",authenticity="Murasaki Shikibu Nikki survives in later copies and appears to be incomplete or stitched together: dated chronicle sections frame an undated letter-essay. The Eiga Monogatari quotes a fuller version. About 20 per cent of a 13th-century illustrated scroll survives.",bio="She was brought in by Michinaga to give his daughter's salon literary weight, and she recorded the birth of his grandson in close ceremonial detail while privately feeling out of place. Her sharp portraits of other women writers, Sei Shōnagon above all, make her the hinge between the two salons.",sources=[{"title":"Diaries of Court Ladies of Old Japan (Omori & Doi 1920), Murasaki diary, full text","url":OM_M},{"title":"The Diary of Lady Murasaki (Wikipedia)","url":"https://en.wikipedia.org/wiki/The_Diary_of_Lady_Murasaki"}]),
 dict(id="michinaga",name="Fujiwara no Michinaga",life="966–1028 (died 4th day 12th month Manju 4, early January 1028 Julian)",role="Head of the Fujiwara clan and nairan from 995; Minister of the Left; regent 1016; chancellor 1017–18; father of three empresses",side="Fujiwara northern house (Michinaga line)",where="The Tsuchimikado mansion and the inner palace, at the centre of every decision",vantage=0,vantage_label="principal actor",form="diary (kanbun daily record, partly autograph)",language="Classical Chinese (kanbun) as written by Japanese courtiers",authenticity="Midō Kanpakuki covers 998–1021, and his own autograph rolls survive at the Yōmei Bunko. Scholars often call it the oldest autograph diary in the world. It is on UNESCO's Memory of the World register (2013). Entries are terse, ungrammatical kanbun with crossings-out.",bio="The man the women's salons were rivalling for. His diary is clipped and practical, full of ceremonies, gifts and illness, and it is often silent where his rivals' diaries are eloquent. He rarely explains himself, but it was his own hand.",sources=[{"title":"Nippon.com: Michinaga's diary and his emotions (autograph, UNESCO)","url":"https://www.nippon.com/fr/japan-topics/g02368/"},{"title":"Fujiwara no Michinaga (Marefa)","url":"https://www.marefa.org/Fujiwara_no_Michinaga"}]),
 dict(id="sanesuke",name="Fujiwara no Sanesuke",life="957–1046",role="Senior noble of the Ononomiya line; Major Counsellor, later Minister of the Right (1021); expert on precedent",side="Fujiwara Ononomiya branch: cooperative but critical of Michinaga",where="At court ceremonies as a high-ranking participant",vantage=1,vantage_label="critical insider",form="diary (kanbun)",language="Classical Chinese (kanbun)",authenticity="Shōyūki (the Ononomiya Minister of the Right's record) survives for roughly 978–1032 in copies with substantial gaps. It is the only source for the text of Michinaga's 'full moon' poem.",bio="He was a stickler for precedent and kept a fifty-year diary. He is the dissenting eye: he records Michinaga's triumphs with an edge, refuses to play along when it counts, and quietly uses Murasaki as a go-between to Shōshi.",sources=[{"title":"Fujiwara no Sanesuke (Wikipedia)","url":"https://en.wikipedia.org/wiki/Fujiwara_no_Sanesuke"},{"title":"MLIT multilingual text: Tsuchimikado and the full moon poem recorded in Shōyūki","url":"https://www.mlit.go.jp/tagengo-db/common/001559792.pdf"},{"title":"Kyoto Univ. of Advanced Science paper: Murasaki as intermediary in Shōyūki","url":"https://lab.kuas.ac.jp/~jinbungakkai/pdf/2024/h2024_05.pdf"}]),
 dict(id="yukinari",name="Fujiwara no Yukinari",life="972–1028",role="Head Chamberlain (kurōdo no tō) and Emperor Ichijō's confidant; one of the 'three brush-masters' of calligraphy",side="Fujiwara (minor branch); Ichijō's man who served Michinaga's purposes",where="Constantly at the emperor's side in the palace",vantage=1,vantage_label="the emperor's private secretary",form="diary (kanbun)",language="Classical Chinese (kanbun)",authenticity="Gonki survives in copies for c. 991–1011, with later fragments. It is the most detailed contemporary account of Teishi's death.",bio="He served the emperor every day and also worked as Michinaga's useful ally, so he sat on both sides of the empress rivalry. He was Sei Shōnagon's friend and sparring partner in poetry, and his account of Teishi's last night is the most intimate the men's diaries give.",sources=[{"title":"President Online: Teishi's death as recorded in Gonki","url":"https://president.jp/articles/-/83981"}]),
 dict(id="izumi",name="Izumi Shikibu",life="c. 976–after 1027",role="Poet; former wife of Tachibana no Michisada; lover of Princes Tametaka and Atsumichi; later in Shōshi's service (c. 1009)",side="Imperial princes' circle, later Shōshi's salon",where="Her house in the capital, then Prince Atsumichi's palace",vantage=2,vantage_label="scandal in the same city",form="diary (nikki, narrated largely in the third person)",language="Classical Japanese (kana)",authenticity="Izumi Shikibu Nikki covers about nine months in 1003–04. It is told in the third person, and its authorship has been debated: some scholars treat it as a tale by another hand. Most accept it as hers or as based on her poems.",bio="She was the period's great love poet. Michinaga nicknamed her the 'floating woman'. Her diary is about private passion conducted through poems, at the same moment as the empress war, and it shows how the court's gossip machine treated a woman with no faction behind her.",sources=[{"title":"Diaries of Court Ladies of Old Japan, Izumi Shikibu diary, full text","url":OM_I},{"title":"Izumi Shikibu (Wikipedia)","url":"https://en.wikipedia.org/wiki/Izumi_Shikibu"}]),
 dict(id="sarashina",name="Sugawara no Takasue's Daughter (author of the Sarashina Nikki)",life="1008–after c. 1059",role="Girl of 12 returning from her father's provincial post in Kazusa; later an occasional lady-in-waiting",side="Provincial-governor class (zuryō), outside the great factions",where="The eastern provinces and the Tōkaidō road, then a modest house in the capital",vantage=3,vantage_label="a provincial child dreaming of the court",form="memoir-diary (written late in life, c. 1060)",language="Classical Japanese (kana)",authenticity="The authoritative text is Fujiwara no Teika's 13th-century copy. A 17th-century rebinding disordered it, and in 1924 scholars restored the order.",bio="She was born the year Atsuhira was born and spent her childhood longing for the Tale of Genji. She is a reader of this chapter's world rather than a player in it, and she shows how the salons' literature reached a provincial girl.",sources=[{"title":"Diaries of Court Ladies of Old Japan, Sarashina diary (on the collection page)","url":OM_C},{"title":"Sarashina Nikki (Wikipedia)","url":"https://en.wikipedia.org/wiki/Sarashina_Nikki"},{"title":"Negri, Sarashina nikki travel section (PAJLS)","url":"https://iris.unive.it/bitstream/10278/27550/7/PAJLS0807.Negri.pdf"}]),
]
E=[]
def e(iso,disp,prec,eye,place,head,dig,conf,note,quote=""):
    E.append(dict(date_iso=iso,date_display=disp,precision=prec,eye=eye,place=place,headline=head,digest=dig,quote=quote,confidence=conf,source_note=note))
e("954","Tenryaku 8 (954)","year","michitsuna-mother","Capital","Kaneie's courtship begins the earliest woman's diary","She opens with Fujiwara no Kaneie's clumsy courtship letters and her reluctant acceptance, and calls her own life as insubstantial as a gossamer haze. Kaneie will father Michinaga by another wife. The book is retrospective here, written years later.","approx","Kagerō Nikki, book 1 opening (954 by scholarly reckoning)")
e("955","Tenryaku 9 (955)","year","michitsuna-mother","Capital","A son is born, and a rival wife appears","She bears Michitsuna and soon discovers Kaneie is visiting another woman, whose house his procession passes. Her jealousy and humiliation become the diary's engine, and the record of a regent's household is told from its least powerful bed.","approx","Kagerō Nikki, book 1 (955)")
e("974","Ten'en 2, end of year (974/975)","year","michitsuna-mother","Capital","The diary ends in a quiet, estranged New Year","The last pages record a cold, almost resigned year's end, with Kaneie largely absent and her hopes turned to her son's career. Fifteen years later, Kaneie's sons will divide the court between them.","approx","Kagerō Nikki, book 3 close (974)")
e("989-11-11","10th day, 10th month, Eiso 1 (989)","day","sanesuke","Imperial palace","The boy emperor's flute moves the court to tears","At a palace music party, the ten-year-old Emperor Ichijō plays the flute, and Sanesuke notes that high and low alike wiped away tears. This ordinary moment of delight comes a year before Teishi enters the court of the gifted child.","verified","Shōyūki, Eiso 1.10.10, as cited by Gendai Business (gendai.media/articles/-/127981)")
e("990-02-23","25th day, 1st month, Shōryaku 1 (990)","day","sanesuke","Imperial palace","Michitaka's daughter Teishi enters the palace","Teishi, about 14, enters as consort at the boy emperor's coming of age, and later in the year (5th day, 10th month) she is raised to chūgū. Her father Michitaka is now the dominant Fujiwara. This entry gives the date only. Shōyūki for these months survives patchily, and the surviving diary detail has not been checked here.","approx","Dates per weblio summary of Teishi's chronology. Recorded in court diaries, but the specific Shōyūki entry was not checked.")
e("993","Winter, Shōryaku 4 (993)","month","sei","Teishi's quarters, palace","A shy newcomer meets the dazzling empress","Sei recalls first entering Teishi's service so embarrassed that she hid her face and would only come out at night. Teishi teased and coaxed her with paintings by lamplight. It is the salon's founding scene, set down long afterwards.","approx","Makura no Sōshi, 'When I first went into service' episode. Year is the usual scholarly dating.")
e("994-04-04","21st day, 2nd month, Shōryaku 5 (994)","day","sei","Shakuzen-ji, capital","Michitaka's splendid dedication at Shakuzen-ji","Sei describes in rapturous detail the procession and robes when Teishi's father Michitaka dedicated a full Buddhist canon at his temple. To her, the family's glory looked permanent. Within fourteen months Michitaka was dead.","approx","Makura no Sōshi, Shakuzen-ji dedication episode. Day as usually given (2.21). Julian conversion computed.")
e("996-06-02","1st day, 5th month, Chōtoku 2 (996)","day","sei","Teishi's residence (Nijō)","Teishi cuts her hair as police search the house","After her brothers Korechika and Takaie were charged with shooting at the retired Emperor Kazan, police searched Teishi's residence, and she cut off her hair on the spot. Sei, who was suspected of sympathising with Michinaga's side, had withdrawn to her home. The Pillow Book says almost nothing about the catastrophe. Its silence is the entry.","approx","Chronology per weblio (Chōtoku 2.5.1). Sei's absence is from Makura no Sōshi's 'staying at home' episode. Julian conversion computed.")
e("998-12-31","10th day, 12th month, Chōtoku 4 (998)","day","sei","Teishi's quarters","The snow mountain wager","After a heavy snowfall, Teishi's people build a mountain of snow in the garden, and the ladies bet on how long it will last. Sei boldly says it will last until the 15th of the New Year, then nurses it obsessively. The salon has already been ruined politically, yet it plays.","approx","Makura no Sōshi, snow mountain episode. Year (Chōtoku 4) and day per usual dating.")
e("999-02-03","15th day, 1st month, Chōhō 1 (999)","day","sei","Teishi's quarters / Sei's home","She loses the snow mountain at the last moment","On the morning she was to win, Sei finds the snow mountain gone. Later she learns Teishi had it secretly cleared to tease her. The joke is affectionate, and it is also a small lesson in who holds power over whose triumph.","approx","Makura no Sōshi, snow mountain episode")
e("999-12-11","1st day, 11th month, Chōhō 1 (999)","day","michinaga","Imperial palace","Michinaga's twelve-year-old Shōshi enters the palace","Michinaga sends his eldest daughter to Ichijō with a lavish trousseau, including screens painted with poems written by the leading nobles. His diary lists arrangements and participants rather than feelings.","approx","Shōshi's entry to court is recorded for 999. Day (11.1) is from standard chronologies, and the Midō Kanpakuki entry was not checked directly.")
e("999-12-17","7th day, 11th month, Chōhō 1 (999)","day","yukinari","Imperial palace","On the day Shōshi becomes consort, Teishi bears a son","Teishi gives birth to Prince Atsuyasu, Ichijō's first son, in the same week that Michinaga's daughter is formally made nyōgo. The two empress lines now each have a claim, a mother and a court diarist watching. Diaries of Michinaga's party treat the coincidence coolly.","approx","Atsuyasu birth date per weblio (Chōhō 1.11.7). Shōshi's nyōgo appointment on the same day is from standard chronology.")
e("1000-02","1st month, Chōhō 2 (1000)","month","yukinari","Imperial palace","Yukinari argues the emperor into two empresses","Yukinari makes the case to Ichijō that Teishi, having taken the tonsure, cannot perform the empress's Fujiwara clan rites. He argues that a second empress is therefore needed, and so opens the way for Shōshi to become chūgū. It was an unprecedented step, and Michinaga recorded his thanks.","approx","Gonki, Chōhō 2, early months. Month is approximate.")
e("1000-04-02","25th day, 2nd month, Chōhō 2 (1000)","day","michinaga","Imperial palace","Shōshi becomes chūgū; Teishi is renamed kōgō","Shōshi is invested as chūgū, and Teishi is restyled kōgō. For the first time one emperor has two empresses. Michinaga's diary treats it as a ceremonial success.","verified","Date per weblio Teishi chronology (Chōhō 2.2.25 = 2 April 1000). Michinaga's entry content is approximate.")
e("1000-06-09","5th day, 5th month, Chōhō 2 (1000)","day","sei","Sanjō residence","Iris festival with the empress's little children","The last datable scene in the Pillow Book is the Tango festival at the Sanjō residence, with Teishi's small prince and princess and the scented iris. It is bright and domestic. Nothing in it hints that Teishi will be dead in seven months.","verified","President Online (president.jp/articles/-/83790): last datable passage, Chōhō 2.5")
e("1000-09","8th month, Chōhō 2 (1000)","month","sei","Temporary palace (Ima-dairi)","The flute by the empress's rooms, the last brief reunion","Teishi comes to the temporary palace for about twenty days, and Ichijō is with her again. The Pillow Book recalls the emperor playing the flute near her quarters this year. It is one of the last scenes of the couple together.","approx","Gendai Business (Pillow Book section on Ichijō's flute, dated 1000) and President Online (Ima-dairi stay, Chōhō 2.8)")
e("1001-01-12","15th day, 12th month, Chōhō 2 (1000)","day","yukinari","Imperial palace","Two white clouds bracket the moon: an omen","Yukinari records two strange white clouds stretching across the sky on either side of the moon, from the eastern hills to the western. He reads them as a sign of ill fortune. His duties keep him near the emperor.","verified","Gonki, Chōhō 2.12.15, per President Online (president.jp/articles/-/83981)")
e("1001-01-13","16th day, 12th month, Chōhō 2 (1000)","day","yukinari","Imperial palace","Teishi dies before dawn after childbirth","Before dawn, news comes that Empress Teishi has died after giving birth to a daughter, at 24 by Yukinari's count. He records the emperor's grief at length. Michinaga's diary and Sanesuke's have no entry for the day, a silence historians have noticed.","verified","Gonki, Chōhō 2.12.16, per President Online. The absence of entries in Midō Kanpakuki and Shōyūki is noted there.")
e("1003-05-13","10th day, 4th month, Chōhō 5 (1003)","day","izumi","Her house in the capital","A spray of orange blossom from the dead lover's brother","Grieving for Prince Tametaka, who died the previous summer, she receives a page from his younger brother Prince Atsumichi bearing a sprig of tachibana, the scent of memory. Her answering poem starts the affair the diary records.","approx","Izumi Shikibu Nikki opening (4th month, 10th day, per Omori text; year 1003 per standard dating; Omori's notes put it a year earlier)")
e("1003-06-08","6th day, 5th month, Chōhō 5 (1003)","day","izumi","Her house in the capital","Flood rains, the Kamo River rising, poems by the hour","In the long early-summer rains, the river overflows and the prince sends poems while not daring to visit, and she answers in kind. Love is conducted almost wholly in writing, under watching eyes.","approx","Izumi Shikibu Nikki (Omori text: 5th month, 6th day). Year per standard dating.")
e("1004-01-12","18th day, 12th month, Chōhō 5 (1003)","day","izumi","Prince Atsumichi's palace","Carried secretly into the prince's palace","Atsumichi fetches her by carriage at night and installs her in his residence. Within weeks his wife's household is in uproar, and the princess leaves for her sister's. Izumi's position outside any great faction leaves her exposed to all the gossip.","approx","Izumi Shikibu Nikki (12th month, 18th day, per Omori). Year per standard dating.")
e("1004-12-17","3rd day, 11th month, Kankō 1 (1004)","day","michinaga","Shōshi's quarters, palace","The emperor plays his flute in Shōshi's rooms","After a banquet given by Michinaga, Ichijō plays several pieces on the flute in Shōshi's quarters. Michinaga records it with evident satisfaction. It is the last documented time the emperor played in company, and this time it was for the other empress.","verified","Midō Kanpakuki, Kankō 1.11.3, per Gendai Business (gendai.media/articles/-/127981)")
e("1007-09-24","11th day, 8th month, Kankō 4 (1007)","day","michinaga","Kinpusen (Mount Yoshino)","Michinaga buries sutras on the holy mountain","After an arduous pilgrimage, Michinaga buries sutras he copied himself in a bronze case at the Kinpusen summit, praying among other things for an heir from Shōshi. A year later she would be pregnant. The inscribed case survives.","approx","Midō Kanpakuki, Kankō 4.8 (Kinpusen pilgrimage). Day per the sutra-case inscription as usually cited; not web-verified in this session.")
e("1008-10-11","10th day, 9th month, Kankō 5 (1008)","day","murasaki","Tsuchimikado mansion","Labour begins amid shouting exorcists","Shōshi's labour begins. The mansion fills with priests, mediums and yin-yang masters shouting down the possessing spirits, and the ladies are packed in so tightly they cannot move. Murasaki records the noise, the heat and the fear.","verified",f"Murasaki Shikibu Nikki ('tenth day of the Long-moon month'), Omori text {OM_M}")
e("1008-10-12","11th day, 9th month, Kankō 5 (1008)","day","murasaki","Tsuchimikado mansion","A prince is born, and Michinaga weeps with relief","At midday Shōshi gives birth to a boy, Prince Atsuhira, the future Go-Ichijō. The afterbirth was slow, and the household's terror turned to elation. Murasaki notes ladies with ruined make-up and Michinaga himself overcome.","verified","Murasaki Shikibu Nikki, 11th day. Western date checked against Wikipedia's 12 October 1008 for Go-Ichijō's birth.")
e("1008-10-12","11th day, 9th month, Kankō 5 (1008)","day","michinaga","Tsuchimikado mansion","The grandson-heir is born: Michinaga's terse record","Michinaga's diary notes the birth of a boy and the ritual arrangements in a few clipped kanbun lines, without the feelings his ladies saw on his face. The birth is the single most important event in his career so far.","approx","Midō Kanpakuki, Kankō 5.9.11 (content summarised from standard accounts; not read directly)")
e("1008-10-16","15th day, 9th month, Kankō 5 (1008)","day","murasaki","Tsuchimikado mansion","Fifth-night celebration under the full moon","Michinaga hosts the fifth-night birth feast under a full moon. Torchlight falls across the garden, servants carry trays of rice balls, and nobles drink and compose poems. Murasaki watches as a participant and also with detachment.","verified","Murasaki Shikibu Nikki ('fifth night'), Omori text")
e("1008-11-16","16th day, 10th month, Kankō 5 (1008)","day","murasaki","Tsuchimikado mansion","The emperor visits; dragon boats on the pond","Emperor Ichijō comes in state to see his son, and music boats with dragon and bird prows float on the lake. Murasaki stares at the bearers straining under the palanquin and feels her own position is no different from theirs.","verified","Murasaki Shikibu Nikki (imperial visit); date per Omori note, which gives '16 October 1008', the lunar date written as if Western. The Julian equivalent is 16 November.")
e("1008-12-01","1st day, 11th month, Kankō 5 (1008)","day","murasaki","Tsuchimikado mansion","Fiftieth-day feast: 'Is young Murasaki here?'","At the prince's fiftieth-day celebration, drink flows. The poet Fujiwara no Kintō peers in and asks whether 'young Murasaki' is about, the first datable allusion to the Tale of Genji. She thinks, but does not say, that no Genji is present either. Michinaga drunkenly demands a poem from her, and she flees with a friend.","verified","Murasaki Shikibu Nikki, 11th month 1st day (Omori text). The Kintō remark and the date's role in Japan's Classics Day are per bestcalendar.jp and precious.jp.")
e("1008-12-01","1st day, 11th month, Kankō 5 (1008)","day","sanesuke","Tsuchimikado mansion (as seen by Murasaki)","Sanesuke counts the ladies' sleeves","In Murasaki's account of the same feast, Sanesuke is seen tallying the layers at the ladies' sleeve openings. Modern commentators read this as him checking compliance with the sumptuary rules, which is typical of the precedent-keeper. Whether he wrote of it himself is not established here: this entry comes through another's eyes.","approx","Murasaki Shikibu Nikki, 11.1, per precious.jp/articles/-/51019. The corresponding Shōyūki entry was not checked.")
e("1008-12-17","17th day, 11th month, Kankō 5 (1008)","day","murasaki","Tsuchimikado to the palace","The empress returns to the palace by night","Shōshi returns to the palace with the prince. Murasaki shares a carriage and is embarrassed at being seen. In the days that follow, Shōshi inspects her father's gifts of fine boxes and poetry anthologies, and the ladies work at copying out the Tale.","verified","Murasaki Shikibu Nikki ('seventeenth of the Frost month'), Omori text. Gift inspection 11.18 per Toyo Keizai (toyokeizai.net/articles/-/821816).")
e("1008-12-20","20th day, 11th month, Kankō 5 (1008)","day","murasaki","Imperial palace","The Gosechi dancers walk between lamps","The young Gosechi dancers enter in a corridor of lamplight so bright that every face is exposed. Murasaki is struck that the girls can bear being stared at, and she reflects uneasily on how used she herself has grown to being seen.","verified","Murasaki Shikibu Nikki, 11.20 (Omori text). Toyo Keizai (toyokeizai.net/articles/-/821816).")
e("1010","c. Kankō 7 (1010), undated letter section","year","murasaki","Palace","Verdict on Sei Shōnagon, Izumi and Akazome Emon","In the undated letter section, Murasaki weighs her contemporaries. Izumi writes captivating poems but behaves improperly. Akazome Emon is dignified. Sei Shōnagon is dreadfully conceited, and her show of Chinese learning will not bear inspection. Sei had left court a decade before, so this is a judgement of a book and a reputation, aimed at a rival salon that no longer existed.","approx","Murasaki Shikibu Nikki, letter section (undated; usually placed c. 1010). Wikipedia summary of the criticism.")
e("1010-02-01","15th day, 1st month, Kankō 7 (1010)","day","murasaki","Imperial palace","Fiftieth day for the second prince","Shōshi's second son Atsunaga, the future Go-Suzaku, born on the 25th day of the 11th month of 1009, has his fiftieth-day rite. Murasaki rushes back to court that morning. It is the last dated scene in her diary. Michinaga now has two imperial grandsons.","verified","Murasaki Shikibu Nikki ('fifteenth day of the Sociable Month'), Omori text")
e("1011-07-01","27th day, 5th month, Kankō 8 (1011)","day","yukinari","Imperial palace","Yukinari talks the dying emperor out of Teishi's son","As Ichijō weakens and contemplates making Teishi's son Atsuyasu crown prince, Yukinari argues him round to Michinaga's grandson Atsuhira, citing precedent and danger. Yukinari's diary records the conversation. Shōshi is said to have resented being bypassed as Atsuyasu's foster mother.","approx","Gonki, Kankō 8.5.27 (standard citation; not read directly)")
e("1011-07-24","21st day, 6th month, Kankō 8 (1011)","day","yukinari","Ichijō-in","The dying emperor's last poem, heard differently","Ichijō, who had abdicated eight days earlier, recites a final poem about leaving someone behind in this world of dew. Yukinari's version seems to address the dead Teishi. Michinaga's diary records a different version, which readers take as addressed to Shōshi. He dies the next day.","approx","Gonki and Midō Kanpakuki, Kankō 8.6.21 (divergent versions; standard scholarly comparison). Death 6.22 = 25 July 1011 per Wikipedia.")
e("1013-07-05","25th day, 5th month, Chōwa 2 (1013)","day","sanesuke","Shōshi's palace (via messenger)","A lady 'daughter of Tametoki' carries his messages","Sanesuke notes that his requests to Empress Dowager Shōshi go through a lady he identifies as the daughter of the governor of Echigo, Tametoki. That was Murasaki. Through his ledger of favours we glimpse the novelist as a working intermediary.","approx","Shōyūki, Chōwa 2 (series from 1.19). Day 5.25 per standard citation. kuas.ac.jp paper confirms the 1013 series.")
e("1018-11-26","16th day, 10th month, Kannin 2 (1018)","day","sanesuke","Tsuchimikado mansion","'This world is my world': Sanesuke refuses to answer","At the banquet for his third daughter Ishi's investiture as Go-Ichijō's empress, Michinaga, half-drunk, recites a poem boasting that his world is like the full moon, lacking nothing. He asks Sanesuke to reply. Sanesuke declines, saying no answer could match it, and leads the company in chanting it over and over. The text survives only because Sanesuke wrote it down.","verified","Shōyūki, Kannin 2.10.16. MLIT text confirms Shōyūki is the poem's source. Investiture date per Fujiwara no Ishi article.",quote="mochizuki no / kaketaru koto mo / nashi to omoeba")
e("1018-11-26","16th day, 10th month, Kannin 2 (1018)","day","michinaga","Tsuchimikado mansion","Three daughters, three empresses: his own bare note","Michinaga's own entry for the day records the investiture ceremony and notes only that he recited a waka and the nobles chanted it together. He does not write down the poem. The man at the summit leaves out his most famous words.","approx","Midō Kanpakuki, Kannin 2.10.16 (standard comparison with Shōyūki; not read directly)")
e("1019-02-12","5th day, 1st month, Kannin 3 (1019)","day","sanesuke","Court (via messenger)","A lady, probably Murasaki, still carrying messages","Sanesuke records a lady-in-waiting, generally identified as Murasaki, relaying matters about his stipend between himself, Michinaga and Shōshi. If the identification holds, she was alive and at work years after the date often given for her death.","verified","Shōyūki, Kannin 3.1.5, per kuas.ac.jp paper (h2024_05.pdf)")
e("1019-04-28","21st day, 3rd month, Kannin 3 (1019)","day","michinaga","Tsuchimikado mansion","Ill, Michinaga takes the tonsure","Suffering chest pains and failing eyesight, Michinaga becomes a lay monk. He keeps his power through his son Yorimichi, the regent. He turns his energy to building the great Amida temple that becomes Hōjō-ji.","approx","Tonsure in Kannin 3 per Kyoto ARC timeline. Day per standard chronology.")
e("1019-05","4th month, Kannin 3 (1019)","month","sanesuke","Capital, council of nobles","Pirates in Kyushu: the court debates rewards","Dispatches from Dazaifu report raiders (the 'Toi', Jurchen) attacking Tsushima, Iki and Hakata, beaten off by local forces under Teishi's brother Takaie. Sanesuke records the council's slow, legalistic debate over whether the defenders deserve rewards when the fighting was done before orders arrived.","approx","Toi invasion per Wikipedia (spring 1019) and Fujiwara no Takaie article. Shōyūki is the main source for the court debate (standard citation; not read directly).")
e("1020-09-22","3rd day, 9th month, Kannin 4 (1020)","day","sarashina","Kazusa province","Leaving the house where she prayed to read Genji","Aged twelve, she leaves the provincial residence where she had a life-size Buddha made and prayed to reach the capital and its tales. As the family moves to a temporary lodging, she looks back and sees the Buddha standing abandoned.","verified","Sarashina Nikki, 9th month 3rd day (Omori text on court.html). Year Kannin 4 = 1020 per standard dating; Omori's note says 1021.")
e("1020-12-18","2nd day, 12th month, Kannin 4 (1020)","day","sarashina","The capital (Sanjō area)","Arrival in the capital after three months","After a three-month journey along the Tōkaidō, past Mount Fuji smoking and the barrier at Ōsaka, they reach the capital after dark. She immediately begs her mother for tales to read.","verified","Sarashina Nikki, 12th month 2nd day (Omori text). Year per standard dating.")
e("1021-04-15","1st day, 3rd month, Jian 1 (1021)","day","sarashina","Capital","Her nurse dies, then calligraphy from a dead girl","Her nurse dies in spring. The same season, the young daughter of Fujiwara no Yukinari, whose calligraphy she had been given as a model, also dies. Grief and literature arrive together, and soon after an aunt gives her more than fifty volumes of Genji.","approx","Sarashina Nikki (nurse's death 3.1, per Omori). Yukinari's daughter's death in the same spring is a well-known episode, and its day is not pinned.")
e("1021","Jian 1 (1021)","year","sarashina","Capital","Fifty volumes of Genji in a bag","Given the whole Tale of Genji, she reads it day and night lying behind her curtains, wanting nothing more, even to be an empress. The book Murasaki wrote inside Michinaga's household has become a provincial girl's whole world. Decades later she would call her absorption foolish.","approx","Sarashina Nikki, Genji episode (c. 1021)")
data=dict(id="heian",title="The Moon Without a Flaw",subtitle="The rival salons of Empresses Teishi and Shōshi and the supremacy of Fujiwara no Michinaga, Heian-kyō, c. 990–1025",span="954–1021",
intro=[
"Around the year 1000, a city of perhaps a hundred thousand people at the foot of the eastern hills held a court of a few thousand nobles, and its politics were made largely in women's rooms. An emperor's heir came from his consort's family, so the Fujiwara clan placed daughters at the emperor's side and waited for sons. Emperor Ichijō had two such wives. Empress Teishi was the daughter of Michitaka, whose branch fell from power in 995–96. Empress Shōshi was the daughter of his younger brother Michinaga, who outlasted everyone.",
"Each empress drew a salon of gifted women around her, and those women wrote. Sei Shōnagon's Pillow Book remembers Teishi's court as a place of jokes, snow mountains and flutes, and it is strikingly silent about that court's disgrace. Murasaki Shikibu, recruited into Shōshi's household, wrote the Tale of Genji and a diary of the birth of Michinaga's grandson. In it she took an acid swipe at Sei Shōnagon, whom she may never have met. Izumi Shikibu's love diary shows what the gossip machine did to a woman without a faction behind her.",
"Beside the women's kana diaries ran the men's. These were daily records in kanbun, a Japanese form of classical Chinese, kept so that precedent could be consulted later. Michinaga's own autograph diary is terse and practical and leaves out what mattered most to him. Sanesuke, his critical senior colleague, wrote down the boastful 'full moon' poem Michinaga himself did not record. Yukinari, the emperor's secretary, gives the most intimate account of Teishi's death, a day both great men's diaries pass over in silence.",
"Setting these side by side shows the same few rooms through glances that do not agree. A birth that Murasaki records as terror, sweat and ruined make-up appears in her patron's diary as a list of rites. A banquet poem survives only because its hearer disapproved. A death goes unrecorded by the men who gained most from it.",
"The chapter is framed by two outsiders. Michitsuna's Mother, wife of Michinaga's father, wrote the first woman's diary a generation earlier. Her niece, the Sarashina diarist, was born in the very year of the imperial birth and arrived in the capital in 1020 as a twelve-year-old who wanted nothing in life except to read Genji. By then Michinaga had his flawless moon, and the salons' rivalry had become literature."],
calendar_note="Dates in date_display follow the Japanese lunisolar calendar of the period (era name, year, month, day). Months are numbered 1–12, with an intercalary month in some years, and the 'year' starts about a month after the Western one, so 12th-month events often fall in January of the next Western year. In date_iso, dates are converted to the Julian calendar (proleptic Gregorian is not used, following the usual Western historians' practice for pre-1582 dates). Conversions were computed with a Chinese/Japanese historical-calendar algorithm and checked against ten published equivalents, such as Teishi's death (16th day 12th month Chōhō 2 = 13 January 1001) and Ichijō's death (22nd day 6th month Kankō 8 = 25 July 1011). The Japanese and Chinese calendars occasionally differed by a day, so single-day conversions should be read as ±1. Some older translations, including Omori and Doi (1920), simply write the lunar month and day as if they were Western dates, for example '16 October 1008' for an event that fell on 16 November 1008 (Julian).",
eyes=eyes,entries=E,
convergences=[
 {"date":"1000-04-02","label":"Two empresses at once: Shōshi made chūgū","eyes":["yukinari","michinaga","sei"],"note":"Yukinari supplies the argument and Michinaga the ceremony. In the Pillow Book, Sei, writing that same spring, shows Teishi's household carrying on its festivals as if nothing had changed."},
 {"date":"1001-01-13","label":"Death of Empress Teishi","eyes":["yukinari","michinaga","sanesuke","sei"],"note":"Only Yukinari writes about it, with omens and the emperor's grief. Michinaga and Sanesuke have no entries for the day, and the Pillow Book never narrates the death at all. Here the silences are the evidence."},
 {"date":"1008-10-12","label":"Birth of Prince Atsuhira at Tsuchimikado","eyes":["murasaki","michinaga"],"note":"Murasaki gives the crush, the shouting and the tears. The grandfather's own record is a few clipped lines of ritual. It was the same room on the same day."},
 {"date":"1008-12-01","label":"The prince's fiftieth-day feast","eyes":["murasaki","sanesuke","michinaga"],"note":"Murasaki's diary is the lens for all three: Michinaga drunk and demanding a poem, Sanesuke counting sleeves, and Kintō's 'young Murasaki' remark, the first datable sign that Genji was being read."},
 {"date":"1018-11-26","label":"Ishi's investiture and the 'full moon' poem","eyes":["sanesuke","michinaga"],"note":"Sanesuke preserves the poem and his own pointed refusal to cap it. Michinaga records only that he recited a waka. Our most famous image of Heian power exists only in a rival's diary."},
 {"date":"1020-12-18","label":"Height of Michinaga's line; a provincial girl arrives","eyes":["sarashina","michinaga"],"note":"In the year Michinaga, now a lay monk, was raising his great Amida hall, a twelve-year-old reached the capital with no thought of politics, only of Genji."}],
ties=[
 {"a":"murasaki","b":"sei","kind":"read each other","note":"Murasaki's diary condemns Sei as conceited and shallow in her Chinese. They probably never served at the same time, so this is a reader judging a rival salon's book."},
 {"a":"murasaki","b":"izumi","kind":"met","note":"Both served Shōshi from about 1009. Murasaki praises Izumi's poems and censures her conduct in the same breath."},
 {"a":"murasaki","b":"michinaga","kind":"met","note":"Her patron and employer. He supplied paper for Genji, teased and pressured her, and appears drunk in her diary."},
 {"a":"murasaki","b":"sanesuke","kind":"met","note":"She sees him at the fiftieth-day feast. Years later he records using a lady he calls Tametoki's daughter as his channel to Shōshi."},
 {"a":"sei","b":"yukinari","kind":"met","note":"Friends and sparring partners. Her famous poem about the Ōsaka barrier (Hyakunin Isshu no. 62) was sent to Yukinari in the course of their teasing correspondence."},
 {"a":"michinaga","b":"sanesuke","kind":"opposite sides","note":"Colleagues for decades. Sanesuke served under Michinaga's supremacy while recording its vanities with a sceptic's pen."},
 {"a":"yukinari","b":"michinaga","kind":"influenced","note":"Yukinari's advice was decisive twice, in 1000 for two empresses and in 1011 for Michinaga's grandson as crown prince."},
 {"a":"michitsuna-mother","b":"michinaga","kind":"relative","note":"She was a wife of Michinaga's father Kaneie, and her son Michitsuna was Michinaga's half-brother."},
 {"a":"michitsuna-mother","b":"sarashina","kind":"relative","note":"The Sarashina diarist was her niece on her mother's side, so two women's diaries frame the age from inside one family."},
 {"a":"sarashina","b":"murasaki","kind":"read each other","note":"The girl's consuming wish was to read Murasaki's Genji. Her diary is the first record of a reader's devotion to it."},
 {"a":"sarashina","b":"yukinari","kind":"mentioned","note":"She practised calligraphy from a model written by Yukinari's young daughter, who died in 1021, and mourns her."},
 {"a":"izumi","b":"michinaga","kind":"mentioned","note":"Michinaga is said to have dubbed her the 'floating woman' (ukareme) for her love life."}],
threads_out=[
 {"to":"long-threads","note":"The Heian nikki founded a Japanese tradition of the literary diary, which runs through medieval travel diaries to Bashō. Michinaga's Midō Kanpakuki, on UNESCO's Memory of the World register, is a landmark in the long history of the autograph diary that this book traces."},
 {"to":"japan-1945","note":"The imperial line that Michinaga's daughters and grandsons secured is the same dynasty whose emperor broadcast the surrender in 1945. The Tsuchimikado mansion site, where Go-Ichijō was born, lies within today's Kyoto Imperial Palace grounds."}],
images=[
 {"url":"https://www.nippon.com/fr/japan-topics/g02368/","title":"Murasaki Shikibu Nikki Emaki, fragment (via Nippon.com, courtesy ColBase)","caption":"A 13th-century scroll scene showing Michinaga's wife Rinshi holding the newborn prince, with Shōshi, Michinaga and Murasaki in the same room: a later visualization of the 1008 birth celebrations.","date":"13th century (Kamakura)","credit":"Tokyo National Museum / ColBase, reproduced by Nippon.com"},
 {"url":OM_C,"title":"Illustrations in Diaries of Court Ladies of Old Japan (1920)","caption":"The 1920 Omori and Doi translation includes period-style plates: court full dress, kichō screens, a nobleman's carriage, a shinden-style mansion plan. These show the physical setting of all three women's diaries.","date":"1920 (reproducing older images)","credit":"Houghton Mifflin, via University of Pennsylvania Digital Library"}],
further=[
 {"title":"Diaries of Court Ladies of Old Japan (Omori & Doi, 1920), full text","url":OM_C},
 {"title":"The Diary of Lady Murasaki (Wikipedia)","url":"https://en.wikipedia.org/wiki/The_Diary_of_Lady_Murasaki"},
 {"title":"Sarashina Nikki (Wikipedia)","url":"https://en.wikipedia.org/wiki/Sarashina_Nikki"},
 {"title":"Emperor Ichijō (Wikipedia)","url":"https://en.wikipedia.org/wiki/Emperor_Ichij%C5%8D"},
 {"title":"Empress Shōshi (Wikipedia)","url":"https://en.wikipedia.org/wiki/Empress_Sh%C5%8Dshi"},
 {"title":"Toi invasion (Wikipedia)","url":"https://en.wikipedia.org/wiki/Toi_invasion"},
 {"title":"Hérail, Poèmes de Fujiwara no Michinaga (review, Monumenta Nipponica)","url":"https://dept.sophia.ac.jp/monumenta/article/poemes-de-fujiwara-no-michinaga-ministre-a-la-cour-de-hei-an-995-1018-by-francine-herail/"}],
vantage_key="0 = Michinaga, the man at the centre; 1 = courtiers and ladies inside the rival salons and councils; 2 = the same capital but outside the empress rivalry (or a generation earlier); 3 = a provincial outsider looking in; 4 is unused.")
P="/tmp/claude-0/-home-claude/fa284f55-6839-573e-8ba4-d29a7355a349/scratchpad/ch-heian.json"
E.sort(key=lambda x:x["date_iso"])
json.dump(data,open(P,"w",encoding="utf-8"),ensure_ascii=False,indent=1)
ids={x["id"] for x in eyes}
assert all(x["eye"] in ids for x in E)
for c in data["convergences"]: assert set(c["eyes"])<=ids
for t in data["ties"]: assert t["a"] in ids and t["b"] in ids
print(len(eyes),len(E),sum(x["confidence"]=="verified" for x in E))
